import java.util.List;
import java.util.Map;

class ClaimOffice {

    private static final int PROCESSING_FEE = 5;
    private static final double FIRST_INSURANCE_SURCHARGE_RATE = 0.10;
    private static final double SWORD_BASE_PREMIUM = 100;

    private final int yearsWithMhpco;

    ClaimOffice(int yearsWithMhpco) {
        this.yearsWithMhpco = yearsWithMhpco;
    }

    int quote(List<Map<String, Object>> items) {
        double policyBasePremium = 0;
        for (Map<String, Object> item : items) {
            policyBasePremium += basePremiumOf(item);
        }
        return roundInOfficeFavour(withPolicyModifiers(policyBasePremium) + PROCESSING_FEE);
    }

    private double basePremiumOf(Map<String, Object> item) {
        return SWORD_BASE_PREMIUM;
    }

    private double withPolicyModifiers(double policyBasePremium) {
        return policyBasePremium + policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
    }

    private int roundInOfficeFavour(double premium) {
        return (int) Math.ceil(premium);
    }
}
EOF
